use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let kept = composed.entries.iter().filter(|e| e.kept).count();
        let message = format!(
            "Digest {}: {} item(s) kept of {} considered",
            composed.date,
            kept,
            composed.considered.len(),
        );
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
